mapper.codeEditorJavascript:
const p=v=>typeof v==='string'?JSON.parse(v):v;
const out=[];
for(const a of (p(input.arr)||[])){let b={};try{b=JSON.parse(a.j)}catch(e){}
const act=(b.activeLeads||[]).map(l=>({c:l.campaignName,st:l.status,sub:l.subStatus,fd:l.followDate,fb:l.followByName}));
const inact=(b.inactiveCampaigns||[]).slice().sort((x,y)=>String(y.timestamp).localeCompare(String(x.timestamp))).slice(0,3).map(l=>({c:l.name,r:l.reason,sr:l.subReason&&l.subReason.name,ag:l.agentName,t:l.timestamp,n:l.note}));
const fu=act.filter(l=>/follow|פולו/i.test(String(l.st||'')+' '+String(l.sub||''))||(l.fd&&l.fb));
const sale=inact.filter(l=>String(l.r||'').toUpperCase()==='CLOSED'||/מכירה|נסגר|עסקה/.test(String(l.sr||'')));
const rec={phone:a.p,active:act,closed:inact};
const why=[];
if(fu.length){rec.followup_open=true;why.push('פולואפ פתוח בטוצ\'ט ('+fu.map(l=>(l.fb||'נציג')+(l.fd?' ל-'+l.fd:'')).join(', ')+')');}
if(sale.length){rec.deal_closed=true;why.push('עסקה נסגרה ('+sale.map(l=>(l.ag||'נציג')+' '+String(l.t||'').slice(0,10)).join(', ')+')');}
if(why.length){rec.skip=true;rec.skip_reason=why.join(' + ')+' – אסור להכניס לדוח איתותי קנייה.';}
out.push(rec);}
return JSON.stringify(out);
